-- Leave bounded context core tables (E05-S01): leave_request, leave_balance,
-- audit_log. Cross-service references (employee, manager) are UUIDs only —
-- no foreign keys outside this schema (§2.4).
-- Must run on PostgreSQL (compose) AND H2 in PostgreSQL mode (local/tests):
-- stick to the common SQL subset — UUIDs are generated by the application.

create table leave_request (
    id                   uuid primary key,
    -- hr employee id (cross-service reference, no FK)
    employee_id          uuid         not null,
    -- keycloak subject of the owner: employee-ownership checks vs jwt.sub
    employee_keycloak_id uuid         not null,
    -- manager relationship SNAPSHOT taken at submit time (cached, §2.5);
    -- null when the request is escalated to HR (BR-02 routing)
    manager_keycloak_id  uuid,
    hr_escalated         boolean      not null,
    leave_type           varchar(20)  not null,
    start_date           date         not null,
    end_date             date         not null,
    business_days        integer      not null,
    reason               varchar(500),
    status               varchar(20)  not null,
    decided_by           uuid,
    decided_at           timestamp with time zone,
    decision_comment     varchar(500),
    created_at           timestamp with time zone not null,
    updated_at           timestamp with time zone not null,
    constraint ck_leave_request_type   check (leave_type in ('ANNUAL', 'SICK', 'UNPAID')),
    constraint ck_leave_request_status check (status in ('SUBMITTED', 'APPROVED', 'REJECTED', 'CANCELLED')),
    constraint ck_leave_request_dates  check (end_date >= start_date),
    constraint ck_leave_request_days   check (business_days > 0)
);

create index ix_leave_request_employee       on leave_request (employee_keycloak_id);
create index ix_leave_request_manager_status on leave_request (manager_keycloak_id, status);
create index ix_leave_request_status         on leave_request (status);

create table leave_balance (
    id                   uuid    primary key,
    employee_id          uuid    not null,
    employee_keycloak_id uuid    not null,
    balance_year         integer not null,
    total_days           integer not null,
    used_days            integer not null,
    created_at           timestamp with time zone not null,
    updated_at           timestamp with time zone not null,
    constraint uq_leave_balance_employee_year unique (employee_keycloak_id, balance_year),
    constraint ck_leave_balance_bounds check (total_days >= 0 and used_days >= 0 and used_days <= total_days)
);

create index ix_leave_balance_employee_id on leave_balance (employee_id);

-- Append-only audit trail (BR-06): rows are only ever inserted. On PostgreSQL
-- the schema grants deny UPDATE/DELETE to the service role; H2 (dev/tests)
-- relies on the code path never issuing them.
create table audit_log (
    id          uuid         primary key,
    actor       varchar(255) not null,
    action      varchar(100) not null,
    resource    varchar(255) not null,
    details     varchar(2000),
    occurred_at timestamp with time zone not null
);

create index ix_audit_log_resource on audit_log (resource);
